    requires always(p).satisfied_by(ex),
    ensures always(always(p)).satisfied_by(ex),
{
    // Let the premise be available.
    let h = always(p).satisfied_by(ex);

    // Expand the definition of `always` / `satisfied_by` and prove the resulting forall.
    assert(forall |j: nat| #[trigger] always(p).satisfied_by(ex.suffix(j))) by {
        // Prove for an arbitrary j.
        arbitrary j;
        // Need to show `always(p).satisfied_by(ex.suffix(j))`, i.e. another forall.
        assert(forall |i: nat| #[trigger] p.satisfied_by(ex.suffix(j).suffix(i))) by {
            arbitrary i;

            // Show `ex.suffix(j).suffix(i)` is the same state as `ex.suffix(j + i)`.
            assert(ex.suffix(j).suffix(i) == ex.suffix(j + i)) by {
                // Unfold `suffix` twice and use arithmetic associativity/commutativity.
                // The equality is extensional over `nat_to_state`.
                assert(forall |k: nat| 
                    ex.suffix(j).suffix(i).nat_to_state(k) == ex.suffix(j + i).nat_to_state(k)) by {
                    arbitrary k;
                    // Unfold the definitions of the nested suffixes.
                    // ex.suffix(j).suffix(i).nat_to_state(k)
                    //   = ex.nat_to_state((k + i) + j)
                    // ex.suffix(j + i).nat_to_state(k)
                    //   = ex.nat_to_state(k + (j + i))
                    assert(ex.nat_to_state((k + i) + j) == ex.nat_to_state(k + (j + i)));
                }
            };

            // Now use the original `always(p)` fact.
            assert(p.satisfied_by(ex.suffix(j).suffix(i)));
            // From `h` we know it holds for all positions.
            assert(h(j + i));
        }
        ;
    }
    ;
}

