proof fn always_double<T>(ex: Execution<T>, p: TempPred<T>)
    requires always(p).satisfied_by(ex),
    ensures always(always(p)).satisfied_by(ex),
{
    let h = always(p).satisfied_by(ex);

    // always(always(p)).satisfied_by(ex)
    //   == forall j. always(p).satisfied_by(ex.suffix(j))
    assert forall|j: nat| #[trigger] always(p).satisfied_by(ex.suffix(j)) by {
        // always(p).satisfied_by(ex.suffix(j))
        //   == forall i. p.satisfied_by(ex.suffix(j).suffix(i))
        assert forall|i: nat| #[trigger] p.satisfied_by(ex.suffix(j).suffix(i)) by {
            // From the premise, we can pick k = i + j.
            assert(p.satisfied_by(ex.suffix(i + j))) by {
                assert(h(i + j));
            }

            // Show the execution shifted by j then i equals shifted by i+j.
            assert(ex.suffix(j).suffix(i) == ex.suffix(i + j)) by {
                assert forall|k: nat|
                    ex.suffix(j).suffix(i).nat_to_state(k)
                        == ex.suffix(i + j).nat_to_state(k)
                    by {
                        // Both sides reduce to `ex.nat_to_state(k + i + j)` up to associativity.
                        assert((k + i) + j == k + (i + j));
                    };
            };

            // Since the two executions are equal, their satisfaction is equal.
            assert(p.satisfied_by(ex.suffix(j).suffix(i))) by {
                assert(p.satisfied_by(ex.suffix(j).suffix(i)) == p.satisfied_by(ex.suffix(i + j)));
                assert(p.satisfied_by(ex.suffix(i + j)));
            }
        };
    };
}

